41	/* base64 for Sec-WebSocket-Key (16 random bytes → 24 chars) */
42	static void b64_encode(const unsigned char *in, int inlen,
43	                       char *out, int outcap)
44	{
45	    static const char tbl[] =
46	        "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
47	    int i = 0, o = 0;
48	    while (i + 2 < inlen && o + 4 < outcap)
49	        {
50	            unsigned int v = (in[i] << 16) | (in[i + 1] << 8) | in[i + 2];
51	            out[o++] = tbl[(v >> 18) & 63];
52	            out[o++] = tbl[(v >> 12) & 63];
53	            out[o++] = tbl[(v >> 6) & 63];
54	            out[o++] = tbl[v & 63];
55	            i += 3;
56	        }
57	    out[o] = '\0';
58	}
