60	/* Escape text for embedding inside a JSON string literal.  User input may
61	 * contain " \ \n \r \t — unescaped they would corrupt the WS message JSON
62	 * and ws_server's cJSON_Parse would drop the message silently. */
63	static void json_escape(const char *in, char *out, size_t outcap)
64	{
65	    size_t o = 0;
66	    for (; *in && o + 6 < outcap; in++)
67	        {
68	            switch (*in)
69	                {
70	                case '"':  out[o++] = '\\'; out[o++] = '"';  break;
71	                case '\\': out[o++] = '\\'; out[o++] = '\\'; break;
72	                case '\n': out[o++] = '\\'; out[o++] = 'n';  break;
73	                case '\r': out[o++] = '\\'; out[o++] = 'r';  break;
74	                case '\t': out[o++] = '\\'; out[o++] = 't';  break;
75	                default:   out[o++] = *in;                    break;
76	                }
