81	/* Send one masked text frame (client → server) */
82	static int ws_send_text(int fd, const char *text)
83	{
84	    size_t len = strlen(text);
85	    unsigned char hdr[14];
86	    int hlen = 0;
87	
88	    hdr[hlen++] = 0x81;                 /* FIN + text */
89	    if (len < 126)
90	        {
91	            hdr[hlen++] = (unsigned char)(0x80 | len);
92	        }
93	    else if (len < 65536)
94	        {
95	            hdr[hlen++] = 0x80 | 126;
96	            hdr[hlen++] = (unsigned char)(len >> 8);
97	            hdr[hlen++] = (unsigned char)(len & 0xFF);
98	        }
99	    else
100	        {
101	            hdr[hlen++] = 0x80 | 127;
102	            for (int i = 7; i >= 0; i--)
103	                hdr[hlen++] = (unsigned char)((len >> (i * 8)) & 0xFF);
104	        }
105	
106	    unsigned char mask[4] = { 0x12, 0x34, 0x56, 0x78 };
107	    memcpy(hdr + hlen, mask, 4);
108	    hlen += 4;
109	
110	    if (send(fd, hdr, hlen, 0) != hlen)
111	        return -1;
112	
113	    for (size_t off = 0; off < len; )
114	        {
115	            size_t todo = len - off;
116	            unsigned char chunk[128];
117	            if (todo > sizeof(chunk))
118	                todo = sizeof(chunk);
119	            for (size_t i = 0; i < todo; i++)
120	                chunk[i] = (unsigned char)text[off + i] ^ mask[(off + i) & 3];
121	            if (send(fd, chunk, todo, 0) != (int)todo)
122	                return -1;
123	            off += todo;
124	        }
125	    return 0;
126	}
