206	static void extract_content(const char *json, char *out, int outcap)
207	{
208	    const char *p = strstr(json, "\"content\"");
209	    if (!p)
210	        {
211	            out[0] = '\0';
212	            return;
213	        }
214	    p = strchr(p, ':');
215	    if (!p)
216	        {
217	            out[0] = '\0';
218	            return;
219	        }
220	    p = strchr(p, '"');
221	    if (!p)
222	        {
223	            out[0] = '\0';
