int ws_server_send(const char* chat_id, const char* text)
{
    if (s_listen_fd < 0 || !s_running)
        return ERROR;

    /* Build JSON response */
    cJSON* resp = cJSON_CreateObject();
    cJSON_AddStringToObject(resp, "type", "response");
    cJSON_AddStringToObject(resp, "content", text);
    cJSON_AddStringToObject(resp, "chat_id", chat_id);
    char* json_str = cJSON_PrintUnformatted(resp);
    cJSON_Delete(resp);
    if (!json_str)
        return ERROR;

    pthread_mutex_lock(&s_clients_mtx);
    ws_client_t* client = find_by_chat_id_locked(chat_id);
    int rc = -1;
    if (client) {
        rc = ws_send_frame(client->fd, json_str, strlen(json_str));
        if (rc != 0) {
            syslog(
                LOG_WARNING,
                "[%s] Send failed to %s (fd will be cleaned up by client thread)\n",
                TAG, chat_id);
            /* Don't remove/close here — the client_thread owns the fd lifecycle.
             * The recv() in client_thread will fail and trigger cleanup. */
        }
    } else {
        syslog(LOG_WARNING, "[%s] No WS client for chat_id=%s\n", TAG, chat_id);
    }
    pthread_mutex_unlock(&s_clients_mtx);

    free(json_str);
    return (client == NULL) ? ERROR : (rc == 0 ? OK : ERROR);
}

/* 2026-08-15 P84：向所有活跃 WS 客户端广播语音事件（小智式文字显示）。
 * 消息形如 {"type":"voice_evt","kind":"stt|llm","text":"..."}。
 * cJSON 负责 JSON 转义（text 可能含 " \ 换行）。 */
int ws_server_broadcast_voice_evt(const char* kind, const char* text)
{
    if (!kind || !text || s_listen_fd < 0 || !s_running)
        return ERROR;

    cJSON* evt = cJSON_CreateObject();
    cJSON_AddStringToObject(evt, "type", "voice_evt");
    cJSON_AddStringToObject(evt, "kind", kind);
    cJSON_AddStringToObject(evt, "text", text);
    char* json_str = cJSON_PrintUnformatted(evt);
    cJSON_Delete(evt);
    if (!json_str)
        return ERROR;

    pthread_mutex_lock(&s_clients_mtx);
    int sent = 0;
    for (int i = 0; i < AGENT_WS_MAX_CLIENTS; i++) {
        if (s_clients[i].active && s_clients[i].fd >= 0) {
            if (ws_send_frame(s_clients[i].fd, json_str,
                    strlen(json_str)) == 0) {
                sent++;
            }
        }
    }
    pthread_mutex_unlock(&s_clients_mtx);

    free(json_str);
    if (sent > 0) {
        syslog(LOG_INFO, "[%s] voice_evt(%s) broadcast to %d client(s)\n",
            TAG, kind, sent);
    }
    return (sent > 0) ? OK : ERROR;
}

