static lv_timer_t *g_ai_timer;
static lv_obj_t   *ai_status_lbl; /* 语音状态（Ready/Listening/Thinking/Speaking） */
static lv_obj_t   *ai_voice_btn;  /* 语音对讲圆圈按钮（按住说话） */
