+int ws_server_broadcast_voice_evt(const char* kind, const char* text)
+{
+    if (!kind || !text || s_listen_fd < 0 || !s_running)
+        return ERROR;
+
+    cJSON* evt = cJSON_CreateObject();
+    cJSON_AddStringToObject(evt, "type", "voice_evt");
+    cJSON_AddStringToObject(evt, "kind", kind);
+    cJSON_AddStringToObject(evt, "text", text);
+    char* json_str = cJSON_PrintUnformatted(evt);
+    cJSON_Delete(evt);
+    if (!json_str)
+        return ERROR;
+
+    pthread_mutex_lock(&s_clients_mtx);
+    int sent = 0;
+    for (int i = 0; i < AGENT_WS_MAX_CLIENTS; i++) {
+        if (s_clients[i].active && s_clients[i].fd >= 0) {
+            if (ws_send_frame(s_clients[i].fd, json_str,
+                    strlen(json_str)) == 0) {
+                sent++;
+            }
+        }
+    }
+    pthread_mutex_unlock(&s_clients_mtx);
+
+    free(json_str);
+    if (sent > 0) {
+        syslog(LOG_INFO, "[%s] voice_evt(%s) broadcast to %d client(s)\n",
+            TAG, kind, sent);
+    }
+    return (sent > 0) ? OK : ERROR;
+}
